description:
Implement a hook that filters a list using `useMemo` so the filtered result is only recomputed when `items` or `predicate` changes.

**Example:**
```tsx
const evens = useMemoFilter([1, 2, 3, 4], n => n % 2 === 0);
// evens === [2, 4]
```

starter_code:
import { useMemo } from 'react';

export function useMemoFilter<T>(items: T[], predicate: (item: T) => boolean): T[] {
  // your code here
}

test_suite:
test('returns items matching predicate', () => {
  const { result } = renderHook(() => useMemoFilter([1, 2, 3, 4, 5], n => n % 2 === 0));
  expect(result.current).toEqual([2, 4]);
});

test('returns empty array when nothing matches', () => {
  const { result } = renderHook(() => useMemoFilter([1, 3, 5], n => n % 2 === 0));
  expect(result.current).toEqual([]);
});

test('returns all items when predicate always true', () => {
  const { result } = renderHook(() => useMemoFilter(['a', 'b', 'c'], () => true));
  expect(result.current).toEqual(['a', 'b', 'c']);
});

test('works with object arrays', () => {
  const items = [{ name: 'Alice', active: true }, { name: 'Bob', active: false }];
  const { result } = renderHook(() => useMemoFilter(items, u => u.active));
  expect(result.current).toHaveLength(1);
  expect(result.current[0].name).toBe('Alice');
});

// __hidden__
test('does not mutate original array', () => {
  const items = [1, 2, 3];
  const { result } = renderHook(() => useMemoFilter(items, n => n > 1));
  expect(result.current).toEqual([2, 3]);
  expect(items).toEqual([1, 2, 3]);
});

solution:
import { useMemo } from 'react';

export function useMemoFilter<T>(items: T[], predicate: (item: T) => boolean): T[] {
  return useMemo(() => items.filter(predicate), [items, predicate]);
}
